class Point {
    // 부모 쪽 점수 필드예요.
    int score;

    // 받은 점수를 부모 쪽 필드에 담아요.
    Point(int score) {
        this.score = score;
    }

    // 이 클래스의 score를 돌려줘요.
    int getScore() {
        return score;
    }
}

// Bonus는 Point를 물려받고 같은 이름 필드를 또 가져요.
class Bonus extends Point {
    // 자식 쪽 점수 필드예요.
    int score;

    Bonus(int score) {
        // 부모 생성자가 부모 쪽 필드를 채워요.
        super(score);
        // 보너스로 곱할 배수예요.
        int times = 2;
        // 자식 쪽 필드에는 배수를 곱해 담아요.
        this.score = score * times;
    }

    // 부모 메서드를 다시 만들어 자식 쪽 score를 돌려줘요.
    int getScore() {
        return score;
    }
}

class Main {
    public static void main(String[] args) {
        // 처음 받은 점수예요.
        int base = 30;
        // 변수 자료형은 Point, 실제 객체는 Bonus예요.
        Point p = new Bonus(base);
        // 점수를 출력해요.
        System.out.println("점수: " + p.score);
    }
}
